{
  "questions": [
    {
      "question": "Tell me about a time you reduced deploy time on a platform you owned.",
      "category": "behavioural",
      "whyAsked": "The posting asks for Kubernetes at scale, so the interviewer will probe how you have delivered platform change.",
      "suggestedStoryId": "S1",
      "answerSketch": {
        "situation": "The payments platform at Canvatech took 30 minutes to deploy and blocked releases.",
        "task": "I owned reducing deploy time without extra headcount.",
        "action": "I migrated the services to Kubernetes and Docker and rebuilt the pipeline.",
        "result": "Deploy time dropped from 30 minutes to 5 minutes and releases went daily.",
        "reflection": "I would instrument the pipeline earlier so the improvement was measurable from day one."
      }
    },
    {
      "question": "How do you lead incident response when a production cache fails?",
      "category": "situational",
      "whyAsked": "The posting names incident response leadership for a payments service.",
      "suggestedStoryId": "S2",
      "answerSketch": {
        "situation": "A Redis cache outage degraded checkout for two hours at Canvatech.",
        "task": "I coordinated the incident response as the on-call lead.",
        "action": "I ran the incident bridge, restored the cache and wrote the postmortem.",
        "result": "Checkout recovered in 40 minutes and repeat incidents fell to zero.",
        "reflection": "I would rehearse the failover path monthly so recovery does not depend on one person."
      }
    }
  ]
}
